sys_script_include.script:
var DepartmentService = Class.create();

DepartmentService.prototype = {

    initialize: function() {
        this.validationUtils = new ValidationUtils();
    },

    /**
     * Check whether a Department record exists.
     *
     * @param {String} departmentSysId
     * @return {Boolean}
     */
    departmentExists: function(departmentSysId) {

        if (this.validationUtils.isEmpty(departmentSysId)) {
            return false;
        }

        var department = new GlideRecord(
            'x_2130921_caresy_0_department'
        );

        if (!department.isValid()) {
            gs.error(
                'DepartmentService: Department table is invalid.'
            );
            return false;
        }

        return department.get(departmentSysId);
    },

    /**
     * Retrieve a Department record.
     *
     * @param {String} departmentSysId
     * @return {GlideRecord|null}
     */
    getDepartment: function(departmentSysId) {

        if (this.validationUtils.isEmpty(departmentSysId)) {
            return null;
        }

        var department = new GlideRecord(
            'x_2130921_caresy_0_department'
        );

        if (!department.isValid()) {
            gs.error(
                'DepartmentService: Department table is invalid.'
            );
            return null;
        }

        if (department.get(departmentSysId)) {
            return department;
        }

        return null;
    },

    /**
     * Check whether a Department is active.
     *
     * @param {String} departmentSysId
     * @return {Boolean}
     */
    isDepartmentActive: function(departmentSysId) {

        var department = this.getDepartment(departmentSysId);

        if (!department) {
            return false;
        }

        return department.getValue('active') == '1';
    },

    type: 'DepartmentService'
};
